package com.ryanjei.orushio.pve.paper;import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;class PaperMapWorldGatewayTest{@Test void offline管理者をロード前検証で拒否する(){assertThrows(SecurityException.class,()->PaperMapWorldGateway.validateAdministrator(false,true,true));}@Test void opまたは権限不足をロード前検証で拒否する(){assertThrows(SecurityException.class,()->PaperMapWorldGateway.validateAdministrator(true,false,true));assertThrows(SecurityException.class,()->PaperMapWorldGateway.validateAdministrator(true,true,false));}@Test void onlineかつopと権限ありを許可する(){assertDoesNotThrow(()->PaperMapWorldGateway.validateAdministrator(true,true,true));}}
